{
  "story": "Start with cats! and a tiny teaching vocabulary. Advance through matching pieces, watching each selection add its vocabulary ID. Compare the reconstructed text with the unchanged input: a word need not correspond to one token.",
  "aha": {
    "stateId": "complete",
    "observation": "A word can span multiple vocabulary tokens, while decoding their IDs reconstructs the original text exactly."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "tokenization-rail",
      "kind": "step-rail",
      "presentation": "Use the canonical algorithm/collection rail within the approved card shell. Keep progress and completed trace here. Reference capture shows complete.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "input-and-vocabulary",
      "kind": "fixed-picture",
      "presentation": "Keep the input above a fixed row of named vocabulary entries. Place Rules above the experiment. Highlight bound active regions without animation.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "matching-callout",
      "kind": "active-callout",
      "presentation": "Anchor to the selected region. Identify the matching operation here; report numeric values only in readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "tokenization-evidence",
      "kind": "value-readout",
      "presentation": "Use aligned labeled rows, ending with Status. Derive readouts from selected entries. IDs are fixed teaching keys, not measurements. Counts use whole tokens without rounding. Text preserves exact characters.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Tokenization step",
      "presentation": "Balanced parameter-control budget: zero; navigation uses this index and Reset. Show Previous and Next, retaining names when disabled. Default to the first state; bounds are the declared states; increment by one state. Navigation changes highlights, emitted IDs, remaining text, and reconstruction. Every state persists until learner action, including complete. Provide visible focus and keyboard operation."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state, empty output, and all defaults. Provide visible focus and keyboard operation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Exact-match teaching tokenizer",
        "regions": [
          {
            "id": "rules",
            "label": "Rules",
            "values": [
              "Illustrative tokenizer and IDs, not a production model.",
              "Choose the longest vocabulary match at the remaining text's start.",
              "Preserve every character; unsupported characters stop tokenization."
            ]
          },
          {
            "id": "input",
            "label": "Input",
            "values": [
              "cats!"
            ]
          },
          {
            "id": "cat-entry",
            "label": "cat entry",
            "values": [
              "cat"
            ]
          },
          {
            "id": "s-entry",
            "label": "s entry",
            "values": [
              "s"
            ]
          },
          {
            "id": "punctuation-entry",
            "label": "! entry",
            "values": [
              "!"
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "ready",
            "label": "Read input",
            "short": "Input",
            "sentence": "Begin at the start of Input.",
            "why": "The vocabulary contains cat, s, and !, but not cats. The input remains visible throughout the experiment.",
            "active": [
              "input"
            ],
            "calloutRegion": "input",
            "readouts": [
              {
                "id": "emitted-ids",
                "label": "Emitted token IDs",
                "value": "Empty"
              },
              {
                "id": "remaining-text",
                "label": "Unconsumed text",
                "value": "cats!"
              },
              {
                "id": "decoded-prefix",
                "label": "Decoded prefix",
                "value": "Empty"
              },
              {
                "id": "token-count",
                "label": "Emitted token count",
                "value": "0"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Ready to match the input prefix."
              }
            ]
          },
          {
            "id": "matched-cat",
            "label": "Match cat",
            "short": "cat",
            "sentence": "Select the cat entry and emit its vocabulary ID.",
            "why": "This entry matches the longest available prefix. Its characters become the decoded prefix; the unmatched suffix remains.",
            "active": [
              "cat-entry"
            ],
            "calloutRegion": "cat-entry",
            "readouts": [
              {
                "id": "emitted-ids",
                "label": "Emitted token IDs",
                "value": "17"
              },
              {
                "id": "remaining-text",
                "label": "Unconsumed text",
                "value": "s!"
              },
              {
                "id": "decoded-prefix",
                "label": "Decoded prefix",
                "value": "cat"
              },
              {
                "id": "token-count",
                "label": "Emitted token count",
                "value": "1"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "The decoded prefix plus unconsumed text still equals Input."
              }
            ]
          },
          {
            "id": "matched-s",
            "label": "Match s",
            "short": "s",
            "sentence": "Select the s entry and append its vocabulary ID.",
            "why": "The word continues in a separate vocabulary piece. Decoding the emitted IDs joins their pieces without adding spaces.",
            "active": [
              "s-entry"
            ],
            "calloutRegion": "s-entry",
            "readouts": [
              {
                "id": "emitted-ids",
                "label": "Emitted token IDs",
                "value": "17, 42"
              },
              {
                "id": "remaining-text",
                "label": "Unconsumed text",
                "value": "!"
              },
              {
                "id": "decoded-prefix",
                "label": "Decoded prefix",
                "value": "cats"
              },
              {
                "id": "token-count",
                "label": "Emitted token count",
                "value": "2"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "The word is reconstructed; punctuation remains unconsumed."
              }
            ]
          },
          {
            "id": "complete",
            "label": "Match punctuation",
            "short": "!",
            "sentence": "Select the ! entry to finish tokenizing Input.",
            "why": "Compare Decoded prefix with Input. The word used multiple vocabulary pieces, yet decoding preserves the complete original text.",
            "active": [
              "input",
              "cat-entry",
              "s-entry",
              "punctuation-entry"
            ],
            "calloutRegion": "punctuation-entry",
            "readouts": [
              {
                "id": "emitted-ids",
                "label": "Emitted token IDs",
                "value": "17, 42, 9"
              },
              {
                "id": "remaining-text",
                "label": "Unconsumed text",
                "value": "Empty"
              },
              {
                "id": "decoded-prefix",
                "label": "Decoded prefix",
                "value": "cats!"
              },
              {
                "id": "token-count",
                "label": "Emitted token count",
                "value": "3"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Complete: decoded text exactly matches Input."
              }
            ]
          }
        ]
      }
    ]
  }
}
